/**
 * audio.js - synthesized sound effects (Web Audio) and haptics.
 * No audio files are needed; everything is generated by oscillators.
 */

let ctx = null;
let muted = false;

// Browsers only allow audio after a user gesture, so this is called on tap.
function getContext() {
  if (!ctx) {
    try {
      ctx = new (window.AudioContext || window.webkitAudioContext)();
    } catch (e) { /* audio unsupported */ }
  }
  if (ctx && ctx.state === 'suspended') ctx.resume();
  return ctx;
}

function tone(freq, dur, type, vol, delay, endFreq) {
  const a = getContext();
  if (!a || muted) return;
  const t = a.currentTime + (delay || 0);
  const osc = a.createOscillator();
  const gain = a.createGain();
  osc.type = type || 'sine';
  osc.frequency.setValueAtTime(freq, t);
  if (endFreq) osc.frequency.exponentialRampToValueAtTime(endFreq, t + dur);
  gain.gain.setValueAtTime(vol || 0.15, t);
  gain.gain.exponentialRampToValueAtTime(0.001, t + dur);
  osc.connect(gain);
  gain.connect(a.destination);
  osc.start(t);
  osc.stop(t + dur + 0.02);
}

// Pentatonic scale steps, so cascades always sound pleasant.
const SCALE = [0, 2, 4, 7, 9, 12, 14, 16, 19, 21, 24];
const note = (i) => 261.6 * Math.pow(2, SCALE[Math.max(0, Math.min(i, 10))] / 12);

export const sfx = {
  select: () => tone(620, 0.07, 'sine', 0.1),
  swap: () => tone(300, 0.1, 'triangle', 0.12, 0, 520),
  bad: () => tone(180, 0.18, 'sawtooth', 0.1, 0, 80),
  drop: () => tone(90, 0.09, 'sine', 0.1, 0, 45),
  // k = index of the piece in this pop wave; pitch climbs with chain and k
  pop: (chain, k) => tone(note(chain - 1 + (k % 6)), 0.22, 'triangle', 0.14, k * 0.035),
  big() {
    tone(130, 0.5, 'sawtooth', 0.18, 0, 40);
    [0, 1, 2, 3].forEach((i) => tone(note(i + 4), 0.3, 'square', 0.06, i * 0.06));
  },
  win: () => [0, 2, 4, 5, 7].forEach((x, i) => tone(note(x), 0.4, 'triangle', 0.18, i * 0.12)),
  lose: () => [4, 2, 0].forEach((x, i) => tone(note(x) / 2, 0.4, 'sawtooth', 0.12, i * 0.18)),
};

export const initAudio = getContext;
export function toggleMute() {
  muted = !muted;
  getContext();
  return muted;
}
export function vibrate(pattern) {
  try { if (navigator.vibrate) navigator.vibrate(pattern); } catch (e) { /* ignore */ }
}
